const d = $input.first().json;
const completionRate = d.action_items_created > 0 ? (d.action_items_completed / d.action_items_created * 100).toFixed(1) : 0;
const report = `Meeting Analytics Report\n${'='.repeat(40)}\n` +
  `Total Meetings: ${d.total_meetings}\n` +
  `Avg Duration: ${parseFloat(d.avg_duration).toFixed(0)} min\n` +
  `Total Meeting Time: ${(d.total_meeting_hours / 60).toFixed(1)} hours\n` +
  `Action Items Created: ${d.action_items_created}\n` +
  `Action Items Completed: ${d.action_items_completed} (${completionRate}%)`;
return [{json:{report, completion_rate: completionRate}}];
